-- schema.sql 다음에 실행합니다. 기존 문항은 덮어쓰지 않습니다.
begin;
insert into energy_private.question_sets(version,questions) values(md5('[{"q":"회의 60분째. 결론만 아직 출근 전.","sub":"내 머릿속에 뜨는 자막은?","a":[["D","“그래서… 오늘 뭐 하기로 한 거죠?”"],["I","“잠깐! 이거 완전 다르게 해보면?”"],["S","“두 분 표정이 심상치 않은데…”"],["C","“근데 아까 숫자랑 지금 숫자가 다른데?”"]]},{"q":"단톡방에 안 읽은 메시지 127개.","sub":"내 손가락이 가장 먼저 하는 일은?","a":[["D","맨 아래로 직행. “그래서 제가 할 일은요?”"],["I","웃긴 짤에 답장. “이건 어디서 구했어요ㅋㅋ”"],["S","묻혔던 질문 발견. “이분 답 아직 못 받으셨어요!”"],["C","처음부터 정독. 이 대화에도 맥락이 있다."]]},{"q":"친구들과 여행. 계획은 “일단 제주”.","sub":"출발 전날, 내가 단톡방에 보내는 말은?","a":[["D","“렌터카 예약 완료. 공항에서 10시에 만나!”"],["I","“여기 봐! 바다 보면서 라면 먹는 데래!”"],["S","“다들 꼭 하고 싶은 거 하나씩 말해봐.”"],["C","“그 식당 화요일 휴무야. 우리 화요일 도착인데?”"]]},{"q":"회식 장소 투표. 30분째 전원 “아무거나”.","sub":"이 무한 루프를 끝내는 나의 한마디는?","a":[["D","“그럼 고기로 갑니다. 예약할게요!”"],["I","“이번엔 루프탑 어때요? 맨날 가던 데 말고!”"],["S","“잠깐, 못 드시는 음식부터 확인해요.”"],["C","“인원·예산·거리 맞는 곳 세 군데 추렸어요.”"]]},{"q":"방탈출 종료 3분 전. 아직 첫 번째 방.","sub":"지금 내 모습은?","a":[["D","“힌트 씁시다. 일단 문부터 열어요!”"],["I","“이 그림 뒤집으면? 아니면 노래 제목?”"],["S","“각자 찾은 거 말해봐요. 합쳐보자!”"],["C","“자물쇠 네 자리. 벽 숫자는 다섯 개. 하나는 함정.”"]]},{"q":"배달 최소금액까지 2,000원 부족.","sub":"모두가 메뉴판만 보고 있을 때 나는?","a":[["D","“사이드 하나 추가. 주문 누릅니다!”"],["I","“처음 보는 이 메뉴, 오늘 도전?”"],["S","“누구 음료 필요한 사람? 같이 맞추자.”"],["C","“배달비랑 묶음할인 비교하면 이 조합이 낫네.”"]]},{"q":"워크숍 장기자랑. 우리 팀 이름부터 안 정해짐.","sub":"나는 어떤 카드로 등장할까?","a":[["D","“팀명은 이걸로! 이제 연습합시다.”"],["I","“입장할 때 슬로모션 하면 대박인데?”"],["S","“무대 부담스러운 분은 소품 같이 만들까요?”"],["C","“제한시간 3분이래요. 음악부터 잘라둘게요.”"]]},{"q":"친구가 “나 카페 차릴까?”라고 했다.","sub":"커피 한 모금 마신 뒤, 나의 첫마디는?","a":[["D","“좋아. 언제 시작할 건데?”"],["I","“낮에는 카페, 밤에는 보드게임? 컨셉 좋다!”"],["S","“너 원래 하고 싶었어? 어떤 카페가 꿈이야?”"],["C","“월세랑 하루 몇 잔 팔아야 하는지 계산해봤어?”"]]},{"q":"단체사진 12번째 촬영. 또 누군가 눈을 감았다.","sub":"나의 다음 행동은?","a":[["D","“마지막 한 장! 셋 하면 찍습니다!”"],["I","“이번엔 다 같이 일부러 눈 감아볼까?”"],["S","“아까 빠진 분 계세요. 다 같이 한 번 더!”"],["C","“연사 켤게요. 찍고 눈 뜬 컷 확인하죠.”"]]},{"q":"캠핑 도착. 텐트 설명서는 바람과 함께 사라졌다.","sub":"이때 내가 하는 말은?","a":[["D","“큰 폴대부터 끼워보자. 일단 세워!”"],["I","“옆집 텐트랑 모양 같네? 힌트 얻어보자!”"],["S","“둘은 텐트, 둘은 짐 정리. 같이 나눠 하자.”"],["C","“제품명으로 설명서 찾았어. 부품부터 맞춰보자.”"]]},{"q":"팀 점심 복권에 당첨! 예산은 넉넉하다.","sub":"내가 맡고 싶은 역할은?","a":[["D","“오늘 안에 예약할게요. 가능한 날짜 주세요!”"],["I","“평소 못 가던 코스요리 어때요?”"],["S","“이번엔 조용히 같이 얘기할 수 있는 곳 찾자.”"],["C","“인원별 가격과 취소 규정 확인할게요.”"]]},{"q":"보드게임 첫 판. 설명이 15분째다.","sub":"속으로 하는 생각은?","a":[["D","“한 판 해보면 알겠지. 일단 시작!”"],["I","“이 캐릭터 능력 조합하면 재밌겠는데?”"],["S","“처음 하는 분들 이해했나? 같이 연습하자.”"],["C","“잠깐. 그럼 동점일 땐 누가 이기죠?”"]]}]'::jsonb::text),'[{"q":"회의 60분째. 결론만 아직 출근 전.","sub":"내 머릿속에 뜨는 자막은?","a":[["D","“그래서… 오늘 뭐 하기로 한 거죠?”"],["I","“잠깐! 이거 완전 다르게 해보면?”"],["S","“두 분 표정이 심상치 않은데…”"],["C","“근데 아까 숫자랑 지금 숫자가 다른데?”"]]},{"q":"단톡방에 안 읽은 메시지 127개.","sub":"내 손가락이 가장 먼저 하는 일은?","a":[["D","맨 아래로 직행. “그래서 제가 할 일은요?”"],["I","웃긴 짤에 답장. “이건 어디서 구했어요ㅋㅋ”"],["S","묻혔던 질문 발견. “이분 답 아직 못 받으셨어요!”"],["C","처음부터 정독. 이 대화에도 맥락이 있다."]]},{"q":"친구들과 여행. 계획은 “일단 제주”.","sub":"출발 전날, 내가 단톡방에 보내는 말은?","a":[["D","“렌터카 예약 완료. 공항에서 10시에 만나!”"],["I","“여기 봐! 바다 보면서 라면 먹는 데래!”"],["S","“다들 꼭 하고 싶은 거 하나씩 말해봐.”"],["C","“그 식당 화요일 휴무야. 우리 화요일 도착인데?”"]]},{"q":"회식 장소 투표. 30분째 전원 “아무거나”.","sub":"이 무한 루프를 끝내는 나의 한마디는?","a":[["D","“그럼 고기로 갑니다. 예약할게요!”"],["I","“이번엔 루프탑 어때요? 맨날 가던 데 말고!”"],["S","“잠깐, 못 드시는 음식부터 확인해요.”"],["C","“인원·예산·거리 맞는 곳 세 군데 추렸어요.”"]]},{"q":"방탈출 종료 3분 전. 아직 첫 번째 방.","sub":"지금 내 모습은?","a":[["D","“힌트 씁시다. 일단 문부터 열어요!”"],["I","“이 그림 뒤집으면? 아니면 노래 제목?”"],["S","“각자 찾은 거 말해봐요. 합쳐보자!”"],["C","“자물쇠 네 자리. 벽 숫자는 다섯 개. 하나는 함정.”"]]},{"q":"배달 최소금액까지 2,000원 부족.","sub":"모두가 메뉴판만 보고 있을 때 나는?","a":[["D","“사이드 하나 추가. 주문 누릅니다!”"],["I","“처음 보는 이 메뉴, 오늘 도전?”"],["S","“누구 음료 필요한 사람? 같이 맞추자.”"],["C","“배달비랑 묶음할인 비교하면 이 조합이 낫네.”"]]},{"q":"워크숍 장기자랑. 우리 팀 이름부터 안 정해짐.","sub":"나는 어떤 카드로 등장할까?","a":[["D","“팀명은 이걸로! 이제 연습합시다.”"],["I","“입장할 때 슬로모션 하면 대박인데?”"],["S","“무대 부담스러운 분은 소품 같이 만들까요?”"],["C","“제한시간 3분이래요. 음악부터 잘라둘게요.”"]]},{"q":"친구가 “나 카페 차릴까?”라고 했다.","sub":"커피 한 모금 마신 뒤, 나의 첫마디는?","a":[["D","“좋아. 언제 시작할 건데?”"],["I","“낮에는 카페, 밤에는 보드게임? 컨셉 좋다!”"],["S","“너 원래 하고 싶었어? 어떤 카페가 꿈이야?”"],["C","“월세랑 하루 몇 잔 팔아야 하는지 계산해봤어?”"]]},{"q":"단체사진 12번째 촬영. 또 누군가 눈을 감았다.","sub":"나의 다음 행동은?","a":[["D","“마지막 한 장! 셋 하면 찍습니다!”"],["I","“이번엔 다 같이 일부러 눈 감아볼까?”"],["S","“아까 빠진 분 계세요. 다 같이 한 번 더!”"],["C","“연사 켤게요. 찍고 눈 뜬 컷 확인하죠.”"]]},{"q":"캠핑 도착. 텐트 설명서는 바람과 함께 사라졌다.","sub":"이때 내가 하는 말은?","a":[["D","“큰 폴대부터 끼워보자. 일단 세워!”"],["I","“옆집 텐트랑 모양 같네? 힌트 얻어보자!”"],["S","“둘은 텐트, 둘은 짐 정리. 같이 나눠 하자.”"],["C","“제품명으로 설명서 찾았어. 부품부터 맞춰보자.”"]]},{"q":"팀 점심 복권에 당첨! 예산은 넉넉하다.","sub":"내가 맡고 싶은 역할은?","a":[["D","“오늘 안에 예약할게요. 가능한 날짜 주세요!”"],["I","“평소 못 가던 코스요리 어때요?”"],["S","“이번엔 조용히 같이 얘기할 수 있는 곳 찾자.”"],["C","“인원별 가격과 취소 규정 확인할게요.”"]]},{"q":"보드게임 첫 판. 설명이 15분째다.","sub":"속으로 하는 생각은?","a":[["D","“한 판 해보면 알겠지. 일단 시작!”"],["I","“이 캐릭터 능력 조합하면 재밌겠는데?”"],["S","“처음 하는 분들 이해했나? 같이 연습하자.”"],["C","“잠깐. 그럼 동점일 땐 누가 이기죠?”"]]}]'::jsonb) on conflict(version) do nothing;
insert into energy_private.settings(id,version) values(1,md5('[{"q":"회의 60분째. 결론만 아직 출근 전.","sub":"내 머릿속에 뜨는 자막은?","a":[["D","“그래서… 오늘 뭐 하기로 한 거죠?”"],["I","“잠깐! 이거 완전 다르게 해보면?”"],["S","“두 분 표정이 심상치 않은데…”"],["C","“근데 아까 숫자랑 지금 숫자가 다른데?”"]]},{"q":"단톡방에 안 읽은 메시지 127개.","sub":"내 손가락이 가장 먼저 하는 일은?","a":[["D","맨 아래로 직행. “그래서 제가 할 일은요?”"],["I","웃긴 짤에 답장. “이건 어디서 구했어요ㅋㅋ”"],["S","묻혔던 질문 발견. “이분 답 아직 못 받으셨어요!”"],["C","처음부터 정독. 이 대화에도 맥락이 있다."]]},{"q":"친구들과 여행. 계획은 “일단 제주”.","sub":"출발 전날, 내가 단톡방에 보내는 말은?","a":[["D","“렌터카 예약 완료. 공항에서 10시에 만나!”"],["I","“여기 봐! 바다 보면서 라면 먹는 데래!”"],["S","“다들 꼭 하고 싶은 거 하나씩 말해봐.”"],["C","“그 식당 화요일 휴무야. 우리 화요일 도착인데?”"]]},{"q":"회식 장소 투표. 30분째 전원 “아무거나”.","sub":"이 무한 루프를 끝내는 나의 한마디는?","a":[["D","“그럼 고기로 갑니다. 예약할게요!”"],["I","“이번엔 루프탑 어때요? 맨날 가던 데 말고!”"],["S","“잠깐, 못 드시는 음식부터 확인해요.”"],["C","“인원·예산·거리 맞는 곳 세 군데 추렸어요.”"]]},{"q":"방탈출 종료 3분 전. 아직 첫 번째 방.","sub":"지금 내 모습은?","a":[["D","“힌트 씁시다. 일단 문부터 열어요!”"],["I","“이 그림 뒤집으면? 아니면 노래 제목?”"],["S","“각자 찾은 거 말해봐요. 합쳐보자!”"],["C","“자물쇠 네 자리. 벽 숫자는 다섯 개. 하나는 함정.”"]]},{"q":"배달 최소금액까지 2,000원 부족.","sub":"모두가 메뉴판만 보고 있을 때 나는?","a":[["D","“사이드 하나 추가. 주문 누릅니다!”"],["I","“처음 보는 이 메뉴, 오늘 도전?”"],["S","“누구 음료 필요한 사람? 같이 맞추자.”"],["C","“배달비랑 묶음할인 비교하면 이 조합이 낫네.”"]]},{"q":"워크숍 장기자랑. 우리 팀 이름부터 안 정해짐.","sub":"나는 어떤 카드로 등장할까?","a":[["D","“팀명은 이걸로! 이제 연습합시다.”"],["I","“입장할 때 슬로모션 하면 대박인데?”"],["S","“무대 부담스러운 분은 소품 같이 만들까요?”"],["C","“제한시간 3분이래요. 음악부터 잘라둘게요.”"]]},{"q":"친구가 “나 카페 차릴까?”라고 했다.","sub":"커피 한 모금 마신 뒤, 나의 첫마디는?","a":[["D","“좋아. 언제 시작할 건데?”"],["I","“낮에는 카페, 밤에는 보드게임? 컨셉 좋다!”"],["S","“너 원래 하고 싶었어? 어떤 카페가 꿈이야?”"],["C","“월세랑 하루 몇 잔 팔아야 하는지 계산해봤어?”"]]},{"q":"단체사진 12번째 촬영. 또 누군가 눈을 감았다.","sub":"나의 다음 행동은?","a":[["D","“마지막 한 장! 셋 하면 찍습니다!”"],["I","“이번엔 다 같이 일부러 눈 감아볼까?”"],["S","“아까 빠진 분 계세요. 다 같이 한 번 더!”"],["C","“연사 켤게요. 찍고 눈 뜬 컷 확인하죠.”"]]},{"q":"캠핑 도착. 텐트 설명서는 바람과 함께 사라졌다.","sub":"이때 내가 하는 말은?","a":[["D","“큰 폴대부터 끼워보자. 일단 세워!”"],["I","“옆집 텐트랑 모양 같네? 힌트 얻어보자!”"],["S","“둘은 텐트, 둘은 짐 정리. 같이 나눠 하자.”"],["C","“제품명으로 설명서 찾았어. 부품부터 맞춰보자.”"]]},{"q":"팀 점심 복권에 당첨! 예산은 넉넉하다.","sub":"내가 맡고 싶은 역할은?","a":[["D","“오늘 안에 예약할게요. 가능한 날짜 주세요!”"],["I","“평소 못 가던 코스요리 어때요?”"],["S","“이번엔 조용히 같이 얘기할 수 있는 곳 찾자.”"],["C","“인원별 가격과 취소 규정 확인할게요.”"]]},{"q":"보드게임 첫 판. 설명이 15분째다.","sub":"속으로 하는 생각은?","a":[["D","“한 판 해보면 알겠지. 일단 시작!”"],["I","“이 캐릭터 능력 조합하면 재밌겠는데?”"],["S","“처음 하는 분들 이해했나? 같이 연습하자.”"],["C","“잠깐. 그럼 동점일 땐 누가 이기죠?”"]]}]'::jsonb::text)) on conflict(id) do nothing;
